     1	const Notifier = require('./Notifier');
     2	
     3	class SmsNotifier extends Notifier {
     4	  constructor(options = {}) {
     5	    super({ ...options, channel: 'sms', maxPerHour: options.maxPerHour || 4 });
     6	    this.senderId = options.senderId || 'APP';
     7	    this.segmentLength = options.segmentLength || 140;
     8	  }
     9	
    10	  validateUser(user) {
    11	    super.validateUser(user);
    12	    if (!user.phone || !/^\+[1-9]\d{6,14}$/.test(user.phone)) {
    13	      throw new TypeError('user.phone must be E.164 for SMS notifications');
    14	    }
    15	  }
    16	
    17	  shouldThrottle(user, message, options = {}) {
    18	    const base = super.shouldThrottle(user, message, options);
    19	    if (base.throttled) {
    20	      return base;
    21	    }
    22	
    23	    if (message.category === 'marketing' && !user.smsOptIn) {
    24	      return {
    25	        throttled: true,
    26	        reason: 'user has not opted into marketing SMS',
    27	        retryAt: null
    28	      };
    29	    }
    30	
    31	    return { throttled: false };
    32	  }
    33	
    34	  format(user, message, options = {}) {
    35	    const formatted = super.format(user, message, options);
    36	    const prefix = message.priority === 'urgent' ? 'URGENT: ' : '';
    37	    const composed = `${prefix}${formatted.title} - ${formatted.body}`;
    38	    const text = this.truncate(composed);
    39	
    40	    return {
    41	      ...formatted,
    42	      to: user.phone,
    43	      from: this.senderId,
    44	      text,
    45	      segments: Math.ceil(text.length / this.segmentLength),
    46	      preview: text
    47	    };
    48	  }
    49	
    50	  truncate(value) {
    51	    if (value.length <= this.segmentLength) {
    52	      return value;
    53	    }
    54	    return `${value.slice(0, this.segmentLength - 1)}…`;
    55	  }
    56	
    57	  async deliver(payload) {
    58	    if (typeof this.transport.sms !== 'function') {
    59	      throw new Error('sms transport is not configured');
    60	    }
    61	    await this.transport.sms(payload);
    62	  }
    63	}
    64	
    65	module.exports = SmsNotifier;
