const THROTTLE_WINDOW_MS = 60 * 60 * 1000;

function validateUser(user) {
  if (!user || typeof user !== 'object') {
    throw new TypeError('user is required');
  }
  if (!user.id) {
    throw new TypeError('user.id is required');
  }
}

function validateMessage(message) {
  if (!message || typeof message !== 'object') {
    throw new TypeError('message is required');
  }
  if (!message.title || !message.body) {
    throw new TypeError('message.title and message.body are required');
  }
}

function applyTemplate(value, user, message) {
  return String(value)
    .replace(/\{\{name\}\}/g, user.name || 'there')
    .replace(/\{\{id\}\}/g, user.id)
    .replace(/\{\{category\}\}/g, message.category || 'general');
}

function formatBase(config, user, message, options = {}) {
  const id = `${config.channel}-${user.id}-${config.now().getTime()}`;
  const locale = options.locale || user.locale || config.defaultLocale;
  const title = applyTemplate(message.title, user, message);
  const body = applyTemplate(message.body, user, message);

  return {
    id,
    channel: config.channel,
    locale,
    title,
    body,
    preview: `${title}: ${body}`.slice(0, 120),
    metadata: {
      category: message.category || 'general',
      priority: message.priority || 'normal',
      generatedAt: config.now().toISOString()
    }
  };
}

function throttleKey(config, user, message) {
  const category = message.category || 'general';
  return `${config.channel}:${user.id}:${category}`;
}

// Throttle rules are evaluated in order. A rule returns a decision to stop
// evaluation, or undefined to defer to the next rule.
function evaluateThrottle(rules, config, user, message, options = {}) {
  for (const rule of rules) {
    const decision = rule(config, user, message, options);
    if (decision) {
      return decision;
    }
  }
  return { throttled: false };
}

function rateLimit(config, user, message, options = {}) {
  if (options.force || message.priority === 'urgent') {
    return undefined;
  }

  const key = throttleKey(config, user, message);
  const now = config.now().getTime();
  const records = (config.throttleStore.get(key) || []).filter(ts => now - ts < THROTTLE_WINDOW_MS);

  if (records.length >= config.maxPerHour) {
    return {
      throttled: true,
      reason: `${config.channel} hourly limit reached`,
      retryAt: new Date(records[0] + THROTTLE_WINDOW_MS).toISOString()
    };
  }

  return undefined;
}

function allowWhen(predicate) {
  return (config, user, message, options) =>
    (predicate(user, message, options) ? { throttled: false } : undefined);
}

function requireMarketingOptIn(optInField, reason) {
  return (config, user, message) => {
    if (message.category === 'marketing' && !user[optInField]) {
      return { throttled: true, reason, retryAt: null };
    }
    return undefined;
  };
}

function recordDelivery(config, user, message) {
  const key = throttleKey(config, user, message);
  const records = config.throttleStore.get(key) || [];
  records.push(config.now().getTime());
  config.throttleStore.set(key, records);
}

function deliverVia(transportKey, label) {
  return async (config, payload) => {
    if (typeof config.transport[transportKey] !== 'function') {
      throw new Error(`${label} transport is not configured`);
    }
    await config.transport[transportKey](payload);
  };
}

module.exports = {
  validateUser,
  validateMessage,
  applyTemplate,
  formatBase,
  throttleKey,
  evaluateThrottle,
  rateLimit,
  allowWhen,
  requireMarketingOptIn,
  recordDelivery,
  deliverVia
};

