const shared = require('./shared');

// Composes a channel definition with the shared notification services.
//
// A channel definition is a plain object:
//   channel           channel name, used in ids, throttle keys, and results
//   defaultMaxPerHour hourly limit when options.maxPerHour is not set
//   settings(options) channel-specific settings merged into the config
//   validateUser(user) channel-specific checks, run after the shared checks
//   throttleRules     ordered rules passed to shared.evaluateThrottle
//   format(config, formatted, user, message, options) extends the shared payload
//   deliver(config, payload) hands the payload to the transport
//
// The returned notifier doubles as the config object passed to shared services
// and channel hooks. Settings are read at call time, so reassigning a setting
// such as `notifier.transport` still takes effect.
function createChannelNotifier(definition, options = {}) {
  const config = {
    channel: definition.channel,
    transport: options.transport || {},
    templates: options.templates || {},
    throttleStore: options.throttleStore || new Map(),
    now: options.now || (() => new Date()),
    defaultSender: options.defaultSender || 'Product Team',
    defaultLocale: options.defaultLocale || 'en-US',
    maxPerHour: options.maxPerHour || definition.defaultMaxPerHour,
    ...definition.settings(options)
  };

  function validateUser(user) {
    shared.validateUser(user);
    definition.validateUser(user);
  }

  function shouldThrottle(user, message, sendOptions = {}) {
    return shared.evaluateThrottle(definition.throttleRules, config, user, message, sendOptions);
  }

  function throttleKey(user, message) {
    return shared.throttleKey(config, user, message);
  }

  function format(user, message, sendOptions = {}) {
    const formatted = shared.formatBase(config, user, message, sendOptions);
    return definition.format(config, formatted, user, message, sendOptions);
  }

  function recordDelivery(user, message) {
    shared.recordDelivery(config, user, message);
  }

  async function deliver(payload) {
    await definition.deliver(config, payload);
  }

  async function send(user, message, sendOptions = {}) {
    validateUser(user);
    shared.validateMessage(message);

    const throttle = shouldThrottle(user, message, sendOptions);
    if (throttle.throttled) {
      return {
        channel: config.channel,
        status: 'throttled',
        reason: throttle.reason,
        retryAt: throttle.retryAt,
        userId: user.id
      };
    }

    const formatted = format(user, message, sendOptions);
    await deliver(formatted);
    recordDelivery(user, message);

    return {
      channel: config.channel,
      status: 'sent',
      userId: user.id,
      id: formatted.id,
      preview: formatted.preview
    };
  }

  return Object.assign(config, {
    send,
    validateUser,
    validateMessage: shared.validateMessage,
    shouldThrottle,
    throttleKey,
    format,
    applyTemplate: shared.applyTemplate,
    recordDelivery,
    deliver
  });
}

module.exports = createChannelNotifier;

