const createChannelNotifier = require('./createChannelNotifier');
const { rateLimit, requireMarketingOptIn, deliverVia } = require('./shared');

const emailChannel = {
  channel: 'email',
  defaultMaxPerHour: 8,

  settings(options) {
    return {
      from: options.from || 'noreply@example.com',
      replyTo: options.replyTo || 'support@example.com',
      unsubscribeBaseUrl: options.unsubscribeBaseUrl || 'https://example.com/unsubscribe'
    };
  },

  validateUser(user) {
    if (!user.email || !user.email.includes('@')) {
      throw new TypeError('user.email is required for email notifications');
    }
  },

  throttleRules: [
    rateLimit,
    requireMarketingOptIn('emailOptIn', 'user has not opted into marketing email')
  ],

  format(config, formatted, user, message) {
    const subjectPrefix = message.category === 'security' ? '[Action Required] ' : '';
    const footer = footerFor(config, user, message);

    return {
      ...formatted,
      to: user.email,
      from: config.from,
      replyTo: config.replyTo,
      subject: `${subjectPrefix}${formatted.title}`,
      text: `${formatted.body}\n\n${footer}`,
      html: `<h1>${escapeHtml(formatted.title)}</h1><p>${escapeHtml(formatted.body)}</p><footer>${escapeHtml(footer)}</footer>`,
      preview: formatted.body.slice(0, 90)
    };
  },

  deliver: deliverVia('email', 'email')
};

function footerFor(config, user, message) {
  if (message.category === 'transactional' || message.category === 'security') {
    return `Sent to ${user.email} because of recent account activity.`;
  }
  const url = `${config.unsubscribeBaseUrl}?user=${encodeURIComponent(user.id)}`;
  return `You can unsubscribe at ${url}.`;
}

function escapeHtml(value) {
  return String(value)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function createEmailNotifier(options = {}) {
  return createChannelNotifier(emailChannel, options);
}

module.exports = createEmailNotifier;

