const smsChannel = {
  channel: 'sms',
  defaultMaxPerHour: 4,

  settings(options) {
    return {
      senderId: options.senderId || 'APP',
      segmentLength: options.segmentLength || 140
    };
  },

  validateUser(user) {
    if (!user.phone || !/^\+[1-9]\d{6,14}$/.test(user.phone)) {
      throw new TypeError('user.phone must be E.164 for SMS notifications');
    }
  },

  throttleRules: [
    rateLimit,
    requireMarketingOptIn('smsOptIn', 'user has not opted into marketing SMS')
  ],

