const createChannelNotifier = require('./createChannelNotifier');
const { allowWhen, rateLimit, deliverVia } = require('./shared');

const slackChannel = {
  channel: 'slack',
  defaultMaxPerHour: 20,

  settings(options) {
    return {
      defaultWorkspace: options.defaultWorkspace || 'main',
      defaultChannel: options.defaultChannel || '#general'
    };
  },

  validateUser(user) {
    if (!user.slackId && !user.slackChannel) {
      throw new TypeError('user.slackId or user.slackChannel is required for Slack notifications');
    }
  },

  throttleRules: [
    allowWhen((user, message, options) => Boolean(options.threadTs)),
    rateLimit
  ],

  format(config, formatted, user, message, options) {
    const channel = options.channel || user.slackChannel || config.defaultChannel;
    const mention = user.slackId ? `<@${user.slackId}> ` : '';
    const text = `${mention}*${formatted.title}*\n${formatted.body}`;

    return {
      ...formatted,
      workspace: user.slackWorkspace || config.defaultWorkspace,
      channel,
      threadTs: options.threadTs || null,
      text,
      blocks: blocksFor(formatted, mention),
      preview: text.replace(/\*/g, '').slice(0, 120)
    };
  },

  deliver: deliverVia('slack', 'slack')
};

function blocksFor(formatted, mention) {
  return [
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `${mention}*${formatted.title}*`
      }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: formatted.body
      }
    },
    {
      type: 'context',
      elements: [
        {
          type: 'mrkdwn',
          text: `Category: ${formatted.metadata.category}`
        }
      ]
    }
  ];
}

function createSlackNotifier(options = {}) {
  return createChannelNotifier(slackChannel, options);
}

module.exports = createSlackNotifier;

