    return {
      ...formatted,
      userId: user.id,
      icon: message.icon || config.defaultIcon,
      actionUrl: options.actionUrl || message.actionUrl || config.defaultAction,
      read: false,
      expiresAt: expiresAt.toISOString(),
      preview: formatted.title
    };
  },

  deliver: deliverVia('inapp', 'in-app')
};

function createInAppNotifier(options = {}) {
  return createChannelNotifier(inAppChannel, options);
}

